import{_ as n,C as r,o,c as i,a9 as t,E as s}from"./chunks/framework.asyjyako.js";const f=JSON.parse('{"title":"PerfChecker Studio in VS Code","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/vscode.md","filePath":"interfaces/vscode.md","lastUpdated":null}'),l={name:"interfaces/vscode.md"};function d(c,e,h,p,g,u){const a=r("DocMedia");return o(),i("div",null,[e[0]||(e[0]=t('<h1 id="PerfChecker-Studio-in-VS-Code" tabindex="-1">PerfChecker Studio in VS Code <a class="header-anchor" href="#PerfChecker-Studio-in-VS-Code" aria-label="Permalink to &quot;PerfChecker Studio in VS Code {#PerfChecker-Studio-in-VS-Code}&quot;">​</a></h1><p>PerfChecker combines Julia performance tests, saved results, plots and optional agent conversations inside VS Code. <strong>Studio opens as a full editor tab</strong>: keep it beside your source, move it into another editor group, or return to the compact PerfChecker views in the activity bar.</p><h2 id="Install-and-prepare" tabindex="-1">Install and prepare <a class="header-anchor" href="#Install-and-prepare" aria-label="Permalink to &quot;Install and prepare {#Install-and-prepare}&quot;">​</a></h2><ol><li><p>Install VS Code <strong>1.96 or newer</strong> and Julia <strong>1.10 or newer</strong>.</p></li><li><p>Install the supplied, qualified <strong>PerfChecker 1.0.0 VSIX</strong> with <strong>Extensions → … → Install from VSIX…</strong>. The matching completed <a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/actions/workflows/Qualification.yml" target="_blank" rel="noreferrer">collection qualification</a> provides it in <code>qualification-vscode-ubuntu-latest-1</code> as <code>perfchecker-vscode.vsix</code>; downloading an Actions artifact requires a GitHub login. Official <a href="https://marketplace.visualstudio.com/items?itemName=mirage-interactive-fr.perfchecker-vscode" target="_blank" rel="noreferrer">Marketplace installation</a> follows confirmation of PerfChecker 1.0.0 in Julia General. Reload VS Code if prompted.</p></li><li><p>Open the package folder. Trust the workspace when you are prepared to execute its Julia code.</p></li><li><p>Prepare a Julia controller environment containing the matching PerfChecker build and the collectors you intend to use. Existing TestItems also require TestItemRunner and the package&#39;s test dependencies.</p></li><li><p>Set <strong>PerfChecker: Runner Project</strong> (<code>perfchecker.runnerProject</code>) to the controller environment. For shared scenarios, set <strong>Scenario Project</strong> (<code>perfchecker.scenarioProject</code>) to the environment containing the measured code and its dependencies.</p></li><li><p>Run <strong>PerfChecker: Open Studio</strong> from the command palette. In a workspace with several folders, select the package to inspect.</p></li></ol><p>Opening Studio reads configuration and presents actions. It does not install packages, start Julia, download a model or launch an agent. A controller should contain <code>HTTP</code> if you enable MCP. JET and other analyzers belong in the environment selected for their workers.</p><p>See <a href="./../guide/installation">Installation</a> for the core and interface packages, and <a href="./vscode-configuration">VS Code configuration</a> for complete settings and environment examples.</p><h2 id="Get-a-first-result" tabindex="-1">Get a first result <a class="header-anchor" href="#Get-a-first-result" aria-label="Permalink to &quot;Get a first result {#Get-a-first-result}&quot;">​</a></h2><p>For a project using <code>@testitem</code>:</p><ol><li><p>Studio → <strong>Test items</strong>, or command palette → <strong>PerfChecker: Discover existing test items</strong>.</p></li><li><p>Open VS Code&#39;s <strong>Testing</strong> view and expand <strong>PerfChecker items</strong>.</p></li><li><p>Select one item and run it. PerfChecker measures the selected item in a fresh worker.</p></li><li><p>Read the collector, unit, sample count and scope beside the measurement.</p></li><li><p>Open the saved visual output to inspect the available distributions and profiles.</p></li></ol><p>The Testing summary duration can include worker startup. The item measurement has its own boundary. A green functional test does not establish a performance budget. Use <a href="./../test-items">TestItems and tags</a> to distinguish shared, functional-only and performance-only items.</p><p>For a suite, use <strong>PerfChecker: Create feature suite</strong> if you need a starter, or configure your existing <code>perf/suite.jl</code>. Studio → <strong>Suite designer</strong> opens the full visual editor. Select a workload, checks and a target, run that selection, then open the resulting report.</p><h2 id="Work-across-the-full-editor" tabindex="-1">Work across the full editor <a class="header-anchor" href="#Work-across-the-full-editor" aria-label="Permalink to &quot;Work across the full editor {#Work-across-the-full-editor}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Surface</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;">Studio</td><td style="text-align:right;">Start the workflow, inspect the selected project and open the next action</td></tr><tr><td style="text-align:right;">Suite designer</td><td style="text-align:right;">Choose features, checks, targets and comparisons</td></tr><tr><td style="text-align:right;">Testing view</td><td style="text-align:right;">Discover and run existing Julia TestItems</td></tr><tr><td style="text-align:right;">Visual output</td><td style="text-align:right;">Inspect saved distributions, allocations, flame graphs and version comparisons</td></tr><tr><td style="text-align:right;">Investigations</td><td style="text-align:right;">Discover scenarios, measure, diagnose and read deterministic advice</td></tr><tr><td style="text-align:right;">Advisor chat</td><td style="text-align:right;">Discuss saved evidence; explicitly request implementation and review its diff</td></tr><tr><td style="text-align:right;">Julia notebook</td><td style="text-align:right;">Run an editable discovery → measurement → diagnosis workflow</td></tr><tr><td style="text-align:right;">PerfChecker terminal</td><td style="text-align:right;">Use a dedicated Julia session in the controller project</td></tr></tbody></table><p>These are VS Code editor tabs and native surfaces. Arrange them with VS Code&#39;s editor groups; the activity bar is an entry point, not the available working area.</p><h2 id="Design-a-suite-and-compare-targets" tabindex="-1">Design a suite and compare targets <a class="header-anchor" href="#Design-a-suite-and-compare-targets" aria-label="Permalink to &quot;Design a suite and compare targets {#Design-a-suite-and-compare-targets}&quot;">​</a></h2><p>The suite editor supports global and per-feature check selection, version ranges, filtering, sorting and ordering. Name targets for a branch, tag, commit, working tree or release, then choose exact or grouped baselines. Grouped references can use median, mean, minimum or maximum aggregation.</p><p>Save the selection with <strong>PerfChecker: Save shared UI configuration</strong>. The default is <code>perf/perfchecker-ui.json</code>; compatible web and documentation interfaces can read the same configuration. Running the selection shows progress and leaves saved evidence for later review.</p><p>The editor separates filtering from selection. Search, package/target filters and release bounds change what is visible without deselecting hidden runs. <strong>Select visible</strong> and <strong>Clear visible</strong> act on the current filter; <strong>Clear selection</strong> affects the entire selection. The counter reports selected runs, visible runs and selected runs outside the filter. <strong>Run N selected</strong> includes those hidden selections, so review the exact identifier preview before execution. <strong>Show more</strong> pages workload groups without restricting bulk selection.</p><p>Collector toggles select or deselect matching runs. Unavailable conditions show their reason. Add targets from discovered branches, tags and recent commits or enter a supported ref/URL, then inspect the comparison matrix. Missing or overlapping references are reported before a run; refreshing the plan preserves existing selections when their identifiers still exist.</p><p>The suite tree follows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package → feature → check type → target</span></span></code></pre></div><p>Read <a href="./../suites-and-comparisons">Suites and comparisons</a> before interpreting a result across environments or machines. Never infer an improvement from a profile weight alone.</p><h2 id="Investigate-and-verify" tabindex="-1">Investigate and verify <a class="header-anchor" href="#Investigate-and-verify" aria-label="Permalink to &quot;Investigate and verify {#Investigate-and-verify}&quot;">​</a></h2><p>Use <strong>PerfChecker: Open investigations</strong> for shared scenarios. <strong>Discover scenarios from tests</strong> inspects declarations and proposes candidates without executing the target program. Proposed candidates need an explicit factory and correctness oracle before they become measurable cases.</p><p>Measure declared cases, diagnose with available analyzers, and choose <strong>Advise from saved evidence</strong>. Missing analyzers appear as unavailable; they are not installed automatically. After a change, rerun the same correctness checks and compare compatible before/after measurements.</p><p><strong>Run bounded investigation</strong> can select declared experiments within count and time budgets. Optional model selection requires structured MCP replies and <code>advisorInvestigates = true</code>; it remains separate from implementation chat.</p><h2 id="Cancel-a-run-and-wait-for-cleanup" tabindex="-1">Cancel a run and wait for cleanup <a class="header-anchor" href="#Cancel-a-run-and-wait-for-cleanup" aria-label="Permalink to &quot;Cancel a run and wait for cleanup {#Cancel-a-run-and-wait-for-cleanup}&quot;">​</a></h2><p>Use <strong>Cancel</strong> in a suite execution notification, the suite Testing profile, an investigation or a native Testing run. PerfChecker asks the Julia controller to interrupt its current task and finish its cleanup. Accepting that request does not mean cleanup has finished: wait for the final run status. Closing a suite or investigation editor also requests cancellation. A new run stays blocked until the previous controller has closed.</p><p>A clean interruption finishes as cancelled. If cleanup fails, the run finishes as failed; <strong>PerfChecker: Show worker output</strong> contains the cause and any retained private inventory directory. See <a href="./../reference/checks">allocation cleanup</a> before handling leftover traces or recovering an inventory.</p><p>The extension allows <strong>60 seconds</strong> for the controller to finish. If that deadline expires, it forces the controller to stop and displays a warning that cleanup was not confirmed. Detached workers, allocation traces or inventories may remain. Closing VS Code forcibly, an operating-system shutdown or repeated interruption can also prevent cleanup; restarting the extension does not delete old <code>.mem</code> files indiscriminately.</p><p>Cancelling advisor chat or an MCP request stops the local conversation. A remote server or agent may continue working after the local request closes. Review the isolated implementation checkout and checkpoint before applying changes; local cancellation does not prove the remote tool stopped.</p><h2 id="Advice-and-explicit-implementation" tabindex="-1">Advice and explicit implementation <a class="header-anchor" href="#Advice-and-explicit-implementation" aria-label="Permalink to &quot;Advice and explicit implementation {#Advice-and-explicit-implementation}&quot;">​</a></h2><p>Studio → <strong>Advisor chat</strong> opens <strong>PerfChecker: Chat with performance advisor</strong>. For an authenticated native Codex CLI, choose <strong>Connect Codex CLI</strong>: the extension checks the installation and starts a temporary local MCP connector with separate advice and implementation tools. Follow the <a href="/PerfChecker/dev/mcp-advisor#Connect-an-authenticated-Codex-CLI">qualified Codex recipe</a>, or configure an external MCP advice tool. Choose saved evidence if useful, then ask a question. Chat also works without evidence for configuration and usage questions; the agent is told no measurements were attached.</p><p>Review the answer. You can apply the advice yourself, or explicitly select <strong>Prepare implementation from reviewed advice</strong>. The latter requires the connected Codex implementation tool or a separately configured external tool, and a Git repository with an existing commit.</p><p>Before sending implementation, the extension warns that generated changes may be incorrect. It saves a Git checkpoint of the current on-disk state and prepares an isolated temporary checkout. The agent works there; the original working tree receives no proposed changes until you inspect the diff and select <strong>Apply reviewed implementation changes</strong>. <strong>Restore implementation checkpoint</strong> reverses that applied patch when the repository has not drifted.</p><p>Read the <a href="./../mcp-advisor">MCP guide</a> for configuration, what is transmitted, checkpoint recovery, cancellation and the filesystem-access requirements of the agent tool.</p><h2 id="Julia,-notebooks-and-terminals" tabindex="-1">Julia, notebooks and terminals <a class="header-anchor" href="#Julia,-notebooks-and-terminals" aria-label="Permalink to &quot;Julia, notebooks and terminals {#Julia,-notebooks-and-terminals}&quot;">​</a></h2><p><strong>PerfChecker: Open Julia terminal</strong> creates a terminal named for the package and starts the selected Julia executable with the controller project. <strong>New investigation notebook</strong> opens an untitled Julia notebook containing explicit discovery, measurement and diagnosis cells. It is yours to edit and save; select an available Julia kernel.</p><p><strong>PerfChecker: Debug current Julia file</strong> delegates a saved Julia source file to the installed Julia VS Code debugger. Debugging needs <code>julialang.language-julia</code>. The debugger and notebook kernel are separate from isolated measurement workers; stepping through a program is not a performance measurement.</p><p>See <a href="./vscode-workflows">Plots, notebooks and Julia tools</a> for supported displays, notebook prerequisites and a practical debugging sequence.</p><h2 id="Companion-and-3D-integrations" tabindex="-1">Companion and 3D integrations <a class="header-anchor" href="#Companion-and-3D-integrations" aria-label="Permalink to &quot;Companion and 3D integrations {#Companion-and-3D-integrations}&quot;">​</a></h2><p>A companion extension can open Studio for an explicit workspace URI using <code>perfchecker.openStudioForWorkspace</code>. Existing suite-editor and live-landscape integration commands remain available. They select the requested package folder rather than silently using the first folder in a multi-root workspace.</p><p>This provides the workspace boundary used by the Etendu/Beautiful Landscape integration. PerfChecker does not implement a new 3D renderer; the companion owns its scene and live graphics workflow. Verify its supported extension versions and selected folder before starting a run. <a href="./vscode-workflows">Plots, notebooks and Julia tools</a> describes the command contract.</p><h2 id="Resolve-common-problems" tabindex="-1">Resolve common problems <a class="header-anchor" href="#Resolve-common-problems" aria-label="Permalink to &quot;Resolve common problems {#Resolve-common-problems}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Symptom</th><th style="text-align:right;">Check</th></tr></thead><tbody><tr><td style="text-align:right;">Studio command missing</td><td style="text-align:right;">Installed extension is the current stable version; reload the extension host</td></tr><tr><td style="text-align:right;">Worker cannot import PerfChecker</td><td style="text-align:right;">Runner Project contains the matching package and a <code>Project.toml</code></td></tr><tr><td style="text-align:right;">Analyzer unavailable</td><td style="text-align:right;">Scenario Project contains that analyzer and its target dependencies</td></tr><tr><td style="text-align:right;">No plots</td><td style="text-align:right;">A completed saved report contains the relevant observations/profile artifacts</td></tr><tr><td style="text-align:right;">Chat refuses the configuration</td><td style="text-align:right;">Protocol is <code>mcp_http</code>, response is <code>text</code>, and an advice tool is selected</td></tr><tr><td style="text-align:right;">Implementation cannot proceed</td><td style="text-align:right;">A separate tool is configured; Git/HEAD exists; all buffers are saved</td></tr><tr><td style="text-align:right;">Wrong folder in multi-root workspace</td><td style="text-align:right;">Reopen Studio and select the intended package</td></tr></tbody></table><p>Use <strong>PerfChecker: Show worker output</strong> for execution diagnostics. See <a href="/PerfChecker/dev/interfaces/vscode-configuration#Troubleshooting">configuration troubleshooting</a> and the <a href="/PerfChecker/dev/mcp-advisor#Troubleshooting">MCP failure table</a> for the next checks.</p><h2 id="Recorded-example" tabindex="-1">Recorded example <a class="header-anchor" href="#Recorded-example" aria-label="Permalink to &quot;Recorded example {#Recorded-example}&quot;">​</a></h2>',47)),s(a,{src:"/examples/bibliography/vscode/native-items.png",alt:"Bibliography export workload passed in VS Code while its format API item remains unrun",caption:"Earlier native Testing controller example: one selected Bibliography item executed. This image does not show the Studio or implementation workflow."}),e[1]||(e[1]=t('<p><a id="Run-one-existing-item"></a><a id="Read-the-result-before-comparing-it"></a><a id="Visual-suite-editor"></a><a id="Results"></a><a id="Optional-investigations"></a></p>',1))])}const v=n(l,[["render",d]]);export{f as __pageData,v as default};
